s = "2574125136"
n = len(s)
for i in range(1, 4):
    for j in range(i + 1, i + 4):
        for k in range(j + 1, j + 4):
            parts = [s[:i], s[i:j], s[j:k], s[k:]]
            if all(part and 0 <= int(part) <= 255 and (part == "0" or not part.startswith("0")) for part in parts):
                print(".".join(parts))
